{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C30"],
      "claim": "Myristic acid, a simple long-chain carboxylic acid, has a human oral bioavailability of 28%, directly demonstrating that a lipophilic ionizable carboxylic acid can exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Ursodeoxycholic acid, a carboxylic-acid-containing amphiphilic molecule, shows 50% systemic availability in healthy subjects, supporting high oral bioavailability for acidic molecules with a carboxylate side chain.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Sodium oxybate, a small hydroxy acid that is fully ionized at physiological pH, has an absolute oral bioavailability of about 27% in humans, supporting high bioavailability despite ionization.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Lefamulin, a structurally complex antibiotic with an ester and amino alcohol, has an absolute oral bioavailability of 25.8% in the fasted state, supporting high bioavailability for complex molecules with moderate permeability liabilities.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Neotame, a carboxylic-acid-containing zwitterionic compound, has a systemic availability of 34.4% in humans, providing further evidence that acidic molecules can achieve oral bioavailability above 20%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues, including simple and complex carboxylic acids, show human oral bioavailability at or above 20%. The physicochemical prior predicting low bioavailability is outweighed by direct human F data from closely transferable molecules, so the query is predicted high.",
  "evidence_gaps": [
    "No direct pharmacokinetic data are available for the query molecule itself.",
    "The query's difluoro-substituted hemiacetal/cyclic ether motif is not exactly represented in the analogue set.",
    "Potential effects of active transport, efflux, food, or first-pass metabolism on the query were not directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

